# %% [markdown]
# # Getting to Know the Synthetic HE Data
#
# **What this notebook is for:** a short, plain-language tour of the
# **synthetic** HE cohort that powers the public demo: who is in it, how
# complete it is, and what sleep, activity and overnight vitals look like,
# overall and by clinical group. Each code cell has a note above it saying
# what it does and why.
#
# > ⚠️ **Synthetic data.** Every patient here was generated by code
# > ([docs/synthetic-data.md](../docs/synthetic-data.md)). Group differences
# > and p-values show what the generator was told to build, not clinical
# > findings.
#
# **How to run it:** *Run → Run All Cells*. It takes under a minute.

# %% [markdown]
# ## Step 1 · Load the data
#
# The dashboard's own loader (`data.py`) builds the same synthetic cohort the
# demo shows (24 patients, fixed random seed), so the numbers here match the
# dashboard. Nothing is downloaded.

# %%
import os
import sys
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.colors import ListedColormap
from matplotlib.patches import Patch
from matplotlib.ticker import FuncFormatter

# The repo folder holds the dashboard's data.py (Jupyter may start in notebooks/ or in the repo).
REPO = next((p for p in (Path.cwd(), *Path.cwd().parents) if (p / "data.py").exists()), None)
if REPO is None:
    raise FileNotFoundError("Can't find the dashboard's data.py: run this notebook from the repo or its notebooks/ folder.")
sys.path.insert(0, str(REPO))
import data as he_data

SOURCE = "synthetic"
df, ORIGIN = he_data.notebook_table(SOURCE)
SYNTHETIC = "synthetic" in ORIGIN
print("Data source:", "synthetic" if SYNTHETIC else "study", f"({ORIGIN})")
if SYNTHETIC:
    print("⚠️  SYNTHETIC DATA. Results are artifacts of the generator settings, not clinical findings.")

plt.rcParams.update({"figure.dpi": 110, "axes.spines.top": False, "axes.spines.right": False,
                     "axes.titlesize": 11, "axes.labelsize": 10})
ID = "name"
DAY0 = he_data.first_day(df)
VALID = df["valid80"].eq(1)          # a valid day: ring worn ≥ 80% of the day
MAIN = df["main_sleep"].eq(True)     # a main night (see Step 4)
MIN_NIGHTS = 14                      # a person counts in per-person summaries with at least this many values


def clock(h, _pos=None):
    """Hours after 18:00 (the dashboard's sleep-time scale) as a clock time: 9.5 → "03:30"."""
    m = int(round((18 + h) * 60)) % 1440
    return f"{m // 60:02d}:{m % 60:02d}"


def per_person(col, mask, min_n=MIN_NIGHTS):
    """Each person's median of `col` over the rows in `mask`, for people with at least `min_n` values."""
    v = df.loc[mask, [ID, col]].dropna()
    g = v.groupby(ID)[col]
    return g.median()[g.size() >= min_n]


# %% [markdown]
# ## Step 2 · Who is in the data?
#
# One row is **one person on one study day**. Clinical details (decompensation,
# HE, Child-Pugh…) were recorded **once, at enrollment**, and are copied onto
# every day. `days_since_start` is the study day; there are no calendar dates.

# %%
people = df.groupby(ID).first()
n_days = df.groupby(ID).size()
print(f"{len(people)} participants, {len(df):,} participant-days, study days "
      f"{int(df['days_since_start'].min())}–{int(df['days_since_start'].max())}")
print(f"Days per person: median {n_days.median():.0f} (range {n_days.min()}–{n_days.max()})")

rows = {"Sex": people["sex"].value_counts().to_dict(),
        "Age (years)": f"median {people['age_yrs'].median():.0f}, IQR {people['age_yrs'].quantile(.25):.0f}–"
                       f"{people['age_yrs'].quantile(.75):.0f}"}
for col in ["grp_decomp", "grp_anyOHE", "grp_ctp_class", "grp_meld_band", "grp_bb_use_t0"]:
    if col in people:
        label = he_data.GROUPS[col.removeprefix("grp_")]["label"]
        rows[label] = people[col].value_counts().sort_index().to_dict()
pd.DataFrame({"people": rows})

# %%
fig, axes = plt.subplots(1, 2, figsize=(10, 3.2))
for sex, ages in people.groupby("sex")["age_yrs"]:
    axes[0].hist(ages.dropna(), bins=range(20, 91, 5), alpha=0.6, label=sex)
axes[0].set(title="Age at enrollment", xlabel="Age (years)", ylabel="People")
axes[0].legend(frameon=False)
axes[1].hist(n_days, bins=20, color="#64748b")
axes[1].set(title="How long each person was followed", xlabel="Study days with a record", ylabel="People")
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 3 · How complete is the data?
#
# Two kinds of completeness matter:
#
# * **Valid days:** the ring was worn ≥ 80% of the day. Steps and activity use
#   only these days.
# * **Main nights:** a usable overnight sleep record (Step 4). Sleep, HRV,
#   heart rate and SpO₂ use only these nights.
#
# A missing day or night is left out, never counted as zero.

# %%
per = pd.DataFrame({"valid days (%)": VALID.groupby(df[ID]).mean() * 100,
                    "main nights (%)": MAIN.groupby(df[ID]).mean() * 100})
print(f"Valid days: {VALID.mean():.0%} of participant-days; per person median {per['valid days (%)'].median():.0f}%")
print(f"Main nights: {MAIN.mean():.0%} of participant-days; per person median {per['main nights (%)'].median():.0f}%")

week = (df["days_since_start"] - DAY0) // 7 + 1
by_week = pd.DataFrame({"valid days": VALID.groupby(week).mean() * 100, "main nights": MAIN.groupby(week).mean() * 100,
                        "people": df.groupby(week)[ID].nunique()})
fig, axes = plt.subplots(1, 2, figsize=(10, 3.2))
axes[0].hist([per["valid days (%)"], per["main nights (%)"]], bins=10, range=(0, 100), label=list(per.columns))
axes[0].set(title="Completeness per person", xlabel="% of the person's study days", ylabel="People")
axes[0].legend(frameon=False)
by_week[["valid days", "main nights"]].plot(ax=axes[1])
axes[1].set(title="Completeness over the study", xlabel="Study week", ylabel="% of participant-days", ylim=(0, 100))
ax2 = axes[1].twinx()
ax2.plot(by_week.index, by_week["people"], color="#94a3b8", ls=":", label="people")
ax2.set_ylabel("People still in the study (dotted)")
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 4 · Sleep, night by night
#
# Oura keeps one sleep record per day, filed on the morning the night ended.
# Its `type` says what it is: `long_sleep` is a real night; `sleep`,
# `late_nap` and `rest` are shorter or daytime records.
#
# A **main night** is a `long_sleep` record with 3–16 h in bed and 1–14 h
# asleep, the same rule the dashboard uses. From each main night:
#
# | Measure | How | Unit |
# |---|---|---|
# | Total sleep | Oura's total sleep duration | h |
# | Sleep efficiency | total sleep ÷ time in bed | % |
# | Awake after sleep onset | awake 5-minute slots after first falling asleep, before the final waking | min |
# | Sleep midpoint | halfway between bedtime and waking | clock time |

# %%
print(f"Main nights: {int(MAIN.sum()):,} of {len(df):,} participant-days")
display(df["type"].fillna("(no sleep record)").value_counts().rename("participant-days").to_frame())

SLEEP = [("sleep_tst_h", "Total sleep", "h"), ("sleep_eff_pct", "Sleep efficiency", "%"),
         ("sleep_waso_min", "Awake after sleep onset", "min"), ("sleep_mid_h18", "Sleep midpoint", "clock time")]
fig, axes = plt.subplots(2, 2, figsize=(10, 6))
summary = {}
for ax, (col, label, unit) in zip(axes.flat, SLEEP):
    v = df.loc[MAIN, col].dropna()
    ax.hist(v, bins=40, color="#3949ab", alpha=0.8)
    ax.set(title=label, xlabel=f"{label} ({unit})", ylabel="Nights")
    if unit == "clock time":
        ax.xaxis.set_major_formatter(FuncFormatter(clock))
    fmt = clock if unit == "clock time" else (lambda x: f"{x:.1f}")
    q = v.quantile([.25, .5, .75])
    summary[label] = {"median": fmt(q[.5]), "middle 50% of nights": f"{fmt(q[.25])}–{fmt(q[.75])}",
                      "people with ≥14 nights": len(per_person(col, MAIN))}
plt.tight_layout(); plt.show()
pd.DataFrame(summary).T

# %% [markdown]
# ## Step 5 · Sleep stages
#
# Each night also has a **hypnogram**: one code per 5 minutes (1 deep,
# 2 light, 3 REM, 4 awake: the Oura convention, still to be confirmed with
# the study team). Below: the share of each stage across all main nights, and
# one example night.

# %%
nights = df[MAIN & df["sleep_phase_5_min"].notna()]
stages = pd.DataFrame([he_data.parse_hypnogram(s) for s in nights["sleep_phase_5_min"]], index=nights.index)
asleep = stages[["deep", "light", "rem"]].sum(axis=1)
shares = stages[["deep", "light", "rem"]].div(asleep.where(asleep > 0), axis=0) * 100
print("Median share of sleep:", ", ".join(f"{k} {v:.0f}%" for k, v in shares.median().items()))

# The example participant: the person with the most main nights (never named).
EXAMPLE = MAIN.groupby(df[ID]).sum().idxmax()
night = nights[nights[ID] == EXAMPLE].iloc[-1]
codes = np.array([int(c) for c in night["sleep_phase_5_min"]])
level = {4: 3, 3: 2, 2: 1, 1: 0}  # awake on top, deep at the bottom
t = night["bedtime_start_h18"] + np.arange(len(codes) + 1) / 12

fig, axes = plt.subplots(1, 2, figsize=(10, 3.2), gridspec_kw={"width_ratios": [1, 2]})
axes[0].boxplot([shares[c].dropna() for c in ["deep", "light", "rem"]], showfliers=False)
axes[0].set_xticks([1, 2, 3], ["Deep", "Light", "REM"])
axes[0].set(title="Sleep stages, all main nights", xlabel="Stage", ylabel="% of time asleep")
axes[1].step(t, [level[c] for c in codes] + [level[codes[-1]]], where="post", color="#3949ab")
axes[1].set(title="One night of the example participant", xlabel="Clock time", ylabel="Stage",
            yticks=[0, 1, 2, 3], yticklabels=["Deep", "Light", "REM", "Awake"])
axes[1].xaxis.set_major_formatter(FuncFormatter(clock))
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 6 · Sleep timing and regularity
#
# A late or drifting sleep midpoint is a circadian sign worth noticing in
# cirrhosis (HE can shift sleep later). **Bedtime variability** is how much
# bedtime moves night to night: the standard deviation of bedtime over the
# main nights of the past 14 study days. Each dot below is one person's
# median of each.

# %%
timing = pd.DataFrame({"midpoint": per_person("sleep_mid_h18", MAIN), "bed_sd": per_person("sleep_bed_sd_min", MAIN)}).dropna()
fig, ax = plt.subplots(figsize=(6, 4))
ax.scatter(timing["midpoint"], timing["bed_sd"], color="#3949ab", alpha=0.7)
ax.xaxis.set_major_formatter(FuncFormatter(clock))
ax.set(title=f"Sleep timing per person (n = {len(timing)})", xlabel="Usual sleep midpoint (clock time)",
       ylabel="Bedtime variability (min)")
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 7 · Daily activity
#
# From Oura's 5-minute activity record, on **valid days** only:
#
# * **Steps:** each person's median steps per day.
# * **24-hour activity profile:** how hard the body is working at each time of
#   day (MET: 1 = resting, 3 = light walking, 6+ = vigorous), with all valid
#   days of everyone stacked on one clock from 04:00 to 04:00.
# * **Actogram:** the example participant's last 60 days, one row per day,
#   coloured by Oura's activity class. Aligned dark-blue blocks at night mean a
#   regular sleep-wake rhythm.

# %%
steps = per_person("steps", VALID)
met = he_data._met_rows(df.loc[VALID, "met_5min"]) if "met_5min" in df else None
hours = he_data.DAY_STARTS_AT + np.arange(he_data.SLOTS) * 5 / 60

fig, axes = plt.subplots(1, 2, figsize=(10, 3.2))
axes[0].hist(steps, bins=15, color="#059669")
axes[0].set(title=f"Steps per person (n = {len(steps)})", xlabel="Median steps per valid day", ylabel="People")
if met is not None and np.isfinite(met).any():
    q = np.nanpercentile(met, [25, 50, 75], axis=0)
    axes[1].fill_between(hours, q[0], q[2], color="#2563eb", alpha=0.25, label="middle 50% of days")
    axes[1].plot(hours, q[1], color="#1e3a8a", label="median")
    axes[1].set_xticks(range(4, 29, 4), [f"{h % 24:02d}:00" for h in range(4, 29, 4)])
    axes[1].legend(frameon=False)
axes[1].set(title="24-hour activity profile, everyone", xlabel="Time of day", ylabel="Activity (MET)")
plt.tight_layout(); plt.show()

# %%
ACT_COLORS = ["#e5e7eb", "#3949ab", "#bfdbfe", "#fcd34d", "#fb923c", "#c2410c"]
mine = df[df[ID] == EXAMPLE].tail(60)
grid = np.array([[int(c) for c in s] if isinstance(s, str) else [0] * he_data.SLOTS for s in mine["class_5_min"]])
fig, ax = plt.subplots(figsize=(10, 4.5))
ax.imshow(grid, aspect="auto", interpolation="nearest", cmap=ListedColormap(ACT_COLORS), vmin=0, vmax=5,
          extent=(4, 28, mine["days_since_start"].max() + 0.5, mine["days_since_start"].min() - 0.5))
ax.set_xticks(range(4, 29, 4), [f"{h % 24:02d}:00" for h in range(4, 29, 4)])
ax.set(title="Rest and activity, day by day (example participant)", xlabel="Time of day", ylabel="Study day")
ax.legend([Patch(color=c) for c in ACT_COLORS], he_data.ACTIVITY_CLASSES, ncol=6, frameon=False,
          loc="upper center", bbox_to_anchor=(0.5, -0.15), fontsize=8)
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 8 · Overnight vitals
#
# Oura measures HRV, average heart rate and SpO₂ **overnight**, so they come
# from main nights. SpO₂ is missing on many nights (not every ring records it).

# %%
VITALS = [("average_hrv", "HRV", "ms"), ("average_heart_rate", "Average heart rate", "bpm"), ("spo2", "SpO₂", "%")]
fig, axes = plt.subplots(1, 3, figsize=(11, 3.2))
for ax, (col, label, unit) in zip(axes, VITALS):
    have = df.loc[MAIN, col].notna().mean()
    v = per_person(col, MAIN)
    ax.hist(v, bins=15, color="#7c3aed", alpha=0.8)
    ax.set(title=f"{label}: on {have:.0%} of main nights", xlabel=f"Median per person ({unit})", ylabel="People")
plt.tight_layout(); plt.show()

# %% [markdown]
# ## Step 9 · Do clinical groups differ?
#
# Each person counts once (their median over ≥ 14 nights or valid days), so
# thousands of nights don't pretend to be thousands of people. The
# **Mann-Whitney test** asks whether one group tends to have higher values.
#
# **Read this as exploratory:** groups are from enrollment (baseline
# differences, not worsening), nothing is adjusted for age, sex or
# medication, and with many comparisons about 1 in 20 reaches p < 0.05 by
# chance.

# %%
try:
    from scipy.stats import mannwhitneyu
except ImportError:
    mannwhitneyu = None
    print("scipy not installed: p-values are skipped (pip install scipy).")

COMPARE = [c for c in ["grp_decomp", "grp_anyOHE"] if c in df and df[c].nunique() == 2]
MEASURES = [("sleep_tst_h", "Total sleep (h)", MAIN), ("sleep_eff_pct", "Sleep efficiency (%)", MAIN),
            ("sleep_mid_h18", "Sleep midpoint (clock)", MAIN), ("steps", "Steps per day", VALID)]
results = []
fig, axes = plt.subplots(len(COMPARE), len(MEASURES), figsize=(12, 3.3 * len(COMPARE)), squeeze=False)
for r, grp in enumerate(COMPARE):
    level = df.groupby(ID)[grp].first()
    for c, (col, label, mask) in enumerate(MEASURES):
        med = per_person(col, mask)
        groups = {k: med[level.reindex(med.index) == k] for k in sorted(level.dropna().unique())}
        ax = axes[r, c]
        ax.boxplot(list(groups.values()), showfliers=False)
        ax.set_xticks(range(1, len(groups) + 1), [f"{k}\nn={len(v)}" for k, v in groups.items()])
        for i, v in enumerate(groups.values(), start=1):
            ax.scatter(np.random.default_rng(0).normal(i, 0.05, len(v)), v, s=10, alpha=0.5)
        p = None
        if mannwhitneyu and all(len(v) >= 5 for v in groups.values()):
            p = mannwhitneyu(*groups.values()).pvalue
        ax.set(title=label + (f"\np = {p:.3f}" if p is not None and p >= 0.001 else "\np < 0.001" if p is not None else ""),
               xlabel=he_data.GROUPS[grp.removeprefix("grp_")]["label"], ylabel=label)
        if col == "sleep_mid_h18":
            ax.yaxis.set_major_formatter(FuncFormatter(clock))
        results.append({"grouping": grp.removeprefix("grp_"), "measure": label, "p": p,
                        **{f"median {k}": round(v.median(), 1) for k, v in groups.items()}})
plt.tight_layout(); plt.show()
pd.DataFrame(results)

# %% [markdown]
# ## Step 10 · Summary, and what the data doesn't have

# %%
lines = [
    f"- **{df[ID].nunique()} participants**, {len(df):,} participant-days; "
    f"{VALID.mean():.0%} valid days and {MAIN.mean():.0%} main nights.",
    f"- Typical night: total sleep {df.loc[MAIN, 'sleep_tst_h'].median():.1f} h, efficiency "
    f"{df.loc[MAIN, 'sleep_eff_pct'].median():.0f}%, midpoint {clock(df.loc[MAIN, 'sleep_mid_h18'].median())}.",
    f"- Median steps per valid day: {df.loc[VALID, 'steps'].median():,.0f}.",
]
if SYNTHETIC:
    lines.insert(0, "**Synthetic cohort: generator artifacts, not clinical findings.**")
from IPython.display import Markdown
Markdown("\n".join(lines))

# %% [markdown]
# **Not in this data** (so not in this notebook):
#
# * **No calendar dates**, only study days and clock times, so no weekday or
#   season.
# * **No event dates**: HE episodes, admissions and medication changes are one
#   value per person at enrollment, so nothing can be lined up "before vs.
#   after" an event.
# * **No repeated labs**: bilirubin, albumin, INR, Child-Pugh and MELD are
#   enrollment values.
# * **No temperature, lowest heart rate or Oura sleep score.**
#
# **Next:** `he_trajectories_phenotypes` follows groups across the study and
# looks for patient "types"; `data_overview` lists every column with its units
# and completeness.
